import React from "react";
import {createRoot} from "react-dom/client";
import {flushSync} from "react-dom";
import {MemoryRouter} from "react-router-dom";
import i18n from "/src/i18n.tsx";
import Book from "/src/models/Book.ts";
import AnnotationWorkspace from "/src/components/annotations/workspace.tsx";
import Viewer from "/src/containers/viewer/component.tsx";
import {useAppStore} from "/src/store/useAppStore.ts";
import {AnnotationService} from "/src/utils/storage/annotationService.ts";
import DatabaseService from "/src/utils/storage/databaseService.ts";
import {openPersistentTxt} from "/src/utils/storage/txtIndexService.ts";
export async function run(){
 await i18n.changeLanguage('en');
 const checks:string[]=[],check=(value:unknown,message:string)=>{if(!value)throw Error(message);checks.push(message);};
 const wait=async(fn:()=>unknown|Promise<unknown>,message:string)=>{const until=Date.now()+20000;while(Date.now()<until){if(await fn())return;await new Promise(resolve=>setTimeout(resolve,25));}throw Error(message);};
 const host=document.getElementById('editor')!,root=createRoot(host);host.style.cssText='position:absolute;inset:0;width:100%;height:100%;background:white;overflow:auto';
 const render=(node:React.ReactNode)=>flushSync(()=>root.render(<React.StrictMode><MemoryRouter>{node}</MemoryRouter></React.StrictMode>));
 const button=(label:string)=>Array.from(host.querySelectorAll<HTMLButtonElement>('button')).find(node=>node.textContent===label)!;
 const book=new Book('fixture','Recovery UI fixture','','','','','TXT','','','','','utf-8');
 await DatabaseService.saveRecord(book,'books');
 useAppStore.getState().handleBooks([book]);useAppStore.getState().handleReadingBook(book);
 const source=await openPersistentTxt(book.key,'','utf-8','');const index=await source.store!.prepare();
 const chapter=index.chapters[0],text=await source.store!.readChapter(chapter),quote='唯一摘录𠀀',start=text.indexOf(quote)-(chapter.bodyStart-chapter.start);
 const small=await AnnotationService.create({bookKey:book.key,kind:'small',notes:'SMALL FORMAL BODY 😀',tag:['keep']},{format:'TXT',sourceTicket:source.store!.sourceTicket,chapterIndex:0,chapterId:chapter.chapterId,start,end:start+quote.length});
 const chapterNote=await AnnotationService.create({bookKey:book.key,kind:'chapter',notes:'CHAPTER FORMAL BODY',tag:[]},{format:'TXT',sourceTicket:source.store!.sourceTicket,chapterIndex:0,chapterId:chapter.chapterId});
 await source.store!.close();
 await window.electronAPI.invoke('phase10-change','insert');
 render(<AnnotationWorkspace/>);
 const bookFilter=host.querySelector<HTMLSelectElement>('select[aria-label="Book"]')!;bookFilter.value=book.key;bookFilter.dispatchEvent(new Event('change',{bubbles:true}));
 await wait(()=>!!button('Validate and rebuild TXT'),'validation entry missing from selected-book workspace');
 check(true,'selected TXT exposes full validation/rebuild and original-source relocation in the existing annotations workspace');
 button('Validate and rebuild TXT').click();
 await wait(()=>host.textContent?.includes('TXT validation and recovery finished.'),'rebuild did not complete');
 await wait(()=>host.textContent?.includes('Recovered: 2'),'recovery summary did not update');
 await new Promise(resolve=>setTimeout(resolve,150));
 await window.electronAPI.invoke('annotation-test-preview','panel');
 check(host.querySelector('[aria-label="TXT validation and recovery"]')?.textContent?.includes('Recovered: 2'),'recovery summary remains stable after paint');
 const restored=await AnnotationService.get(small.key);
 check(restored?.notes===small.notes&&restored.bindings[0].start_index===1&&restored.bindings[0].status==='active','UI rebuild restores a shifted binding and preserves formal body');
 let stats=await window.electronAPI.invoke('phase10-ui-stats');
 check(stats.completeHash&&stats.wholeSourceReads===0,'UI rebuild validates complete SHA-256 without whole-source Renderer transfer');
 const panel=host.querySelector<HTMLElement>('[aria-label="TXT validation and recovery"]')!;
 const resultButton=Array.from(panel.querySelectorAll<HTMLButtonElement>('li button')).find(node=>node.textContent==='Chapter 1')!;resultButton.click();
 await wait(()=>!!host.querySelector('.annotation-modal textarea'),'recovery result did not open the original annotation editor');
 check(true,'recovery result opens the original editor for manual binding and retained content');
 await window.electronAPI.invoke('annotation-test-preview','editor');
 button('Close').click();
 await window.electronAPI.invoke('phase10-change','delete-quote');button('Validate and rebuild TXT').click();
 await wait(async()=>!(await AnnotationService.get(small.key))?.bindings.some(b=>b.status==='active'),'deleted excerpt was not invalidated');
 await wait(()=>panel.textContent?.includes('Original excerpt was not found'),'missing-quote explanation not visible');
 const deleted=await AnnotationService.get(small.key);
 check(deleted?.notes===small.notes&&deleted.bindings[0].quote===quote&&deleted.bindings[0].status==='invalid','deleted excerpt keeps its body, quote and original location available for review');
 await window.electronAPI.invoke('phase10-change','hold');button('Validate and rebuild TXT').click();
 await wait(async()=>(await window.electronAPI.invoke('phase10-ui-stats')).held,'slow rebuild did not start');
 const previous=(await window.electronAPI.invoke('phase10-ui-stats')).generation;
 button('Cancel').click();await window.electronAPI.invoke('phase10-change','release');
 await wait(async()=>!(await window.electronAPI.invoke('phase10-ui-stats')).building,'cancelled rebuild cleanup incomplete');
 check((await window.electronAPI.invoke('phase10-ui-stats')).generation===previous,'UI cancel preserves the published generation and annotations');
 await window.electronAPI.invoke('phase10-change','missing');
 document.getElementById('page-area')?.remove();
 useAppStore.setState(state=>({reader:{...state.reader,readerMode:'scroll'}}));
 render(<Viewer book={book} rendition={null} isShow={true} handleLeaveReader={()=>{}} handleEnterReader={()=>{}}/>);
 await wait(()=>host.textContent?.includes('Original TXT source is missing'),'actual Viewer missing-source state absent');
 check(!!button('Locate original TXT'),'actual Viewer offers original TXT relocation instead of a stale cache');
 button('Locate original TXT').click();
 await wait(()=>!!useAppStore.getState().reader.htmlBook?.rendition?.isTxtWindowActive?.(),'actual Viewer did not reopen the relocated source');
 const viewer=useAppStore.getState().reader.htmlBook.rendition;
 await wait(()=>!!viewer.getPosition().txtWindow,'relocated reader did not become readable');
 stats=await window.electronAPI.invoke('phase10-ui-stats');
 check(stats.relocatedPathPersisted&&useAppStore.getState().book.currentBook.key===book.key,'relocation persists the existing book path through books.db without creating a new book');
 check((await AnnotationService.get(chapterNote.key))?.notes===chapterNote.notes&&(await AnnotationService.get(small.key))?.notes===small.notes,'relocation keeps all formal annotation bodies attached to the original book key');
 await wait(()=>viewer.getDocument()?.body.textContent?.includes('正文保留'),'relocated source text did not finish mounting: '+viewer.getDocument()?.body.textContent?.slice(0,120));
 check(stats.wholeSourceReads===0&&viewer.getDocument().body.textContent.includes('正文保留'),'relocated source reads actual current text through the bounded normal compiled reader');
 await window.electronAPI.invoke('annotation-test-preview','native');
 root.unmount();await viewer.removeContent();
 return {passed:true,cases:checks.length,checks,userDatabaseOpened:false,normalCompiledEngine:true};
}
